def prime_fib(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def fibonacci_generator():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    count = 0
    for fib in fibonacci_generator():
        if is_prime(fib):
            count += 1
            if count == n:
                return fib

# Approach: This function generates Fibonacci numbers and checks if they are prime.
# It uses a helper function to check for primality and a generator to produce Fibonacci numbers.
# The function iterates over the Fibonacci sequence, counting prime numbers until it reaches the n-th one.
```

